import { TaskRepository } from '../domain/TaskRepository';
import { ProjectRepository } from '../domain/ProjectRepository';
import { ListTasksRequest, ListTasksResponse } from './dtos';

export class ListTasksUseCase {
  constructor(
    private taskRepository: TaskRepository,
    private projectRepository: ProjectRepository,
  ) {}

  execute(request: ListTasksRequest): ListTasksResponse {
    const project = this.projectRepository.findById(request.projectId);
    if (!project) {
      throw new Error('Project not found');
    }

    let tasks = this.taskRepository.findByProjectId(request.projectId);

    if (request.status && request.assigneeId) {
      tasks = tasks.filter(
        (t) => t.status === request.status && t.assignedToUserId === request.assigneeId,
      );
    } else if (request.status) {
      tasks = this.taskRepository.findByProjectIdAndStatus(request.projectId, request.status);
    } else if (request.assigneeId) {
      tasks = this.taskRepository.findByProjectIdAndAssignee(request.projectId, request.assigneeId);
    }

    return {
      tasks: tasks.map((t) => ({
        id: t.id,
        projectId: t.projectId,
        title: t.title,
        description: t.description,
        dueDate: t.dueDate,
        status: t.status,
        assignedToUserId: t.assignedToUserId,
      })),
    };
  }
}

